"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["92089"],{14533(e){e.exports=JSON.parse('{"id":"FIN-1330","slug":"crypto-exchange","term":"Crypto Exchange","also_known_as":[],"difficulty":"Advanced","definition":"A crypto exchange is a platform where people can buy, sell and trade cryptocurrencies and other digital assets, either for traditional currencies or for other cryptocurrencies.","explanation":["Centralized exchanges are run by companies that hold customers\' funds, match buy and sell orders and often offer other services such as custody, lending and staking. Decentralized exchanges allow users to trade directly from their own wallets using smart contracts, without a central operator holding their funds.","For example, a person might open an account on a centralized exchange, verify their identity, deposit money from their bank account and use it to buy cryptocurrency, which the exchange holds on their behalf unless they withdraw it to their own wallet.","Exchanges have played a central role in the growth of cryptocurrency markets, but they also carry risks. Several major exchanges have collapsed, been hacked or misused customer funds, most notably FTX in 2022, leaving customers with large losses.","Regulation of crypto exchanges has increased in many countries, with requirements covering licensing, anti-money laundering checks, safeguarding customer assets and disclosure. Users should understand whether their funds are held separately and what protections apply."],"note":"","total":1500,"prev":{"slug":"cross-selling","term":"Cross-Selling"},"next":{"slug":"crypto-wallet","term":"Crypto Wallet"}}')}}]);